import XCTest

/// Main path of milestone M4: a file arrives as the share extension leaves
/// it → the Add screen opens prefilled (system suggested from the
/// extension) → upload → Transfers shows it sent → the game is in the
/// library → swipe to delete → trash → empty the trash.
///
/// XCUITest cannot drive the document picker: the file is generated by the
/// app at launch (`RL_UITEST_SHARE_FILE=<name>:<bytes>`, Debug only) and
/// stored in the share inbox, exactly as the extension does.
final class AddFileUITests: XCTestCase {
    override func setUp() {
        continueAfterFailure = false
    }

    /// Against the fake pak (`RL_DEMO=1`).
    @MainActor
    func testAddFileThenDeleteInDemoMode() throws {
        let app = XCUIApplication()
        app.launchArguments += GameDataUITest.englishArguments
        app.launchEnvironment["RL_DEMO"] = "1"
        app.launchEnvironment["RL_UITEST_SHARE_FILE"] = "UITest Homebrew.gba:6291456"
        app.launch()
        app.open(URL(string: PairingUITests.demoLink)!)
        try addSharedFileAndDelete(app, name: "UITest Homebrew", timeout: 20, systemLabel: "Game Boy Advance")
    }

    /// Against a real pak (`make headless` on the Mac), found with Bonjour.
    /// Disabled unless the pairing link printed by the pak is given:
    ///
    ///     TEST_RUNNER_RL_UITEST_PAIR_URL='reminislink://pair?...' \
    ///       TEST_RUNNER_RL_UITEST_SHARE_BYTES=209715200 xcodebuild test ...
    ///
    /// `RL_UITEST_SHARE_BYTES` sets the size of the file (default 8 MiB;
    /// 200 MiB for the acceptance test of docs/specs/09).
    @MainActor
    func testAddFileThenDeleteAgainstHeadlessPak() throws {
        let environment = ProcessInfo.processInfo.environment
        guard let link = environment["RL_UITEST_PAIR_URL"], let url = URL(string: link) else {
            throw XCTSkip("Set TEST_RUNNER_RL_UITEST_PAIR_URL to the pairing link of a running pak (make headless).")
        }
        let bytes = environment["RL_UITEST_SHARE_BYTES"].flatMap(Int.init) ?? 8 << 20
        let name = "UITest \(Int(Date().timeIntervalSince1970))"
        let app = XCUIApplication()
        app.launchArguments += GameDataUITest.englishArguments
        app.launchEnvironment["RL_RESET_STORE"] = "1"
        app.launchEnvironment["RL_UITEST_SHARE_FILE"] = "\(name).gba:\(bytes)"
        app.launch()
        app.open(url)
        try addSharedFileAndDelete(app, name: name, timeout: max(60, Double(bytes) / 1_000_000), systemLabel: nil)
    }

    @MainActor
    private func addSharedFileAndDelete(_ app: XCUIApplication, name: String, timeout: TimeInterval, systemLabel: String?) throws {
        // Pairing, then the Add screen opens for the shared file.
        let done = app.buttons["pairing.done"]
        XCTAssertTrue(done.waitForExistence(timeout: 30), "pairing did not finish")
        done.tap()
        let send = app.buttons["add.send"]
        XCTAssertTrue(send.waitForExistence(timeout: 30), "the Add screen did not open")
        XCTAssertTrue(app.staticTexts["\(name).gba"].waitForExistence(timeout: 10))
        if let systemLabel {
            XCTAssertTrue(app.buttons.matching(NSPredicate(format: "label CONTAINS %@", systemLabel)).firstMatch
                .waitForExistence(timeout: 10), "system not suggested")
        }
        attachScreenshot(app, "add")
        send.tapWhenEnabled(timeout: 20)

        // Transfers: the upload ends.
        XCTAssertTrue(app.staticTexts["upload.status"].waitForExistence(timeout: 20) || app.staticTexts["upload.done"].exists)
        XCTAssertTrue(app.staticTexts["upload.done"].waitForExistence(timeout: timeout),
                      "upload not finished: \(app.staticTexts["upload.status"].label)")
        attachScreenshot(app, "transfers")

        // Library (M11: its tab, every game in one list, searched): the
        // game is there; swipe to delete it.
        GameDataUITest.openLibraryTab(app, timeout: 20)
        let systemRow = app.buttons["system.GBA"]
        if systemRow.waitForExistence(timeout: 3) {
            systemRow.tap()
        } else {
            GameDataUITest.search(app, name)
        }
        let game = app.buttons["game.\(name)"]
        XCTAssertTrue(game.waitForExistence(timeout: 20), "game not in the library")
        game.swipeLeft()
        app.buttons["game.delete"].tapAfterWaiting()
        // The pak's preview (M8) is read before Delete is enabled.
        app.buttons["delete.confirm"].tapWhenEnabled(timeout: 20)
        XCTAssertTrue(app.descendants(matching: .any)["delete.result"].firstMatch.waitForExistence(timeout: 20)
            || app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", name)).firstMatch.exists)
        attachScreenshot(app, "deleted")
        XCTAssertFalse(app.descendants(matching: .any)["error"].exists, "an error is shown")
        app.buttons["delete.emptyNow"].tapAfterWaiting(timeout: 20)
        app.buttons["delete.emptyConfirm"].tapAfterWaiting(timeout: 10)
        XCTAssertTrue(app.descendants(matching: .any)["delete.emptied"].firstMatch.waitForExistence(timeout: 20))
        app.buttons["delete.done"].tap()
        XCTAssertTrue(game.waitForNonExistence(timeout: 20), "game still listed")
    }

    @MainActor
    private func attachScreenshot(_ app: XCUIApplication, _ name: String) {
        let attachment = XCTAttachment(screenshot: app.screenshot())
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}
